package com.google.cloud.translate.spi.v2;

import static com.google.common.base.MoreObjects.firstNonNull;

import com.google.api.client.http.GenericUrl;
import com.google.api.client.http.HttpRequestInitializer;
import com.google.api.client.http.HttpTransport;
import com.google.api.client.json.jackson2.JacksonFactory;
import com.google.api.services.translate.v3.Translate;
import com.google.api.services.translate.v3.model.DetectedLanguage;
import com.google.api.services.translate.v3.model.SupportedLanguage;
import com.google.api.services.translate.v3.model.Translation;
import com.google.cloud.http.HttpTransportOptions;
import com.google.cloud.translate.TranslateException;
import com.google.cloud.translate.TranslateOptions;
import com.google.common.base.Function;
import com.google.common.collect.ImmutableList;
import com.google.common.collect.Lists;
import java.io.IOException;
import java.util.List;
import java.util.Map;

public class HttpTranslateRpc implements TranslateRpc {

  private final TranslateOptions options;
  private final Translate translate;

  public HttpTranslateRpc(TranslateOptions options) {
    HttpTransportOptions transportOptions = (HttpTransportOptions) options.getTransportOptions();
    HttpTransport transport = transportOptions.getHttpTransportFactory().create();
    HttpRequestInitializer initializer = transportOptions.getHttpRequestInitializer(options);
    this.options = options;
    translate =
        new Translate.Builder(transport, new JacksonFactory(), initializer)
            .setRootUrl(options.getHost())
            .setApplicationName(options.getApplicationName())
            .build();
  }

  private static TranslateException translate(IOException exception) {
    return new TranslateException(exception);
  }

  @Override
  public List<List<DetectedLanguage>> detect(List<String> texts) {
    try {
      // V3 API requires detecting language for each text separately
      List<List<DetectedLanguage>> allDetections = Lists.newArrayListWithCapacity(texts.size());
      for (String text : texts) {
        com.google.api.services.translate.v3.Translate.Projects.Locations.DetectLanguage request =
            translate.projects().locations().detectLanguage("projects/-/locations/global");
        request.setContent(text);
        com.google.api.services.translate.v3.model.DetectLanguageResponse response = request.execute();
        List<DetectedLanguage> detections = response.getDetections();
        allDetections.add(detections != null ? detections : ImmutableList.<DetectedLanguage>of());
      }
      return allDetections;
    } catch (IOException ex) {
      throw translate(ex);
    }
  }

  @Override
  public List<SupportedLanguage> listSupportedLanguages(Map<Option, ?> optionMap) {
    try {
      String targetLanguage =
          firstNonNull(
              Option.TARGET_LANGUAGE.getString(optionMap), options.getTargetLanguage());
      com.google.api.services.translate.v3.Translate.Projects.GetSupportedLanguages request =
          translate.projects().getSupportedLanguages("projects/-");
      if (targetLanguage != null) {
        request.setLanguageCode(targetLanguage);
      }
      com.google.api.services.translate.v3.model.SupportedLanguages response = request.execute();
      List<SupportedLanguage> languages = response.getLanguages();
      return languages != null ? languages : ImmutableList.<SupportedLanguage>of();
    } catch (IOException ex) {
      throw translate(ex);
    }
  }

  @Override
  public List<Translation> translate(List<String> texts, Map<Option, ?> optionMap) {
    try {
      String targetLanguage =
          firstNonNull(Option.TARGET_LANGUAGE.getString(optionMap), options.getTargetLanguage());
      String sourceLanguage = Option.SOURCE_LANGUAGE.getString(optionMap);
      String model = Option.MODEL.getString(optionMap);
      String format = Option.FORMAT.getString(optionMap);

      // V3 API translates multiple texts in one call
      com.google.api.services.translate.v3.Translate.Projects.TranslateText request =
          translate.projects().translateText("projects/-");
      request.setContents(texts);
      request.setTargetLanguageCode(targetLanguage);
      if (sourceLanguage != null) {
        request.setSourceLanguageCode(sourceLanguage);
      }
      if (model != null) {
        request.setModel(model);
      }
      if (format != null) {
        request.setMimeType(format);
      }
      com.google.api.services.translate.v3.model.TranslateTextResponse response = request.execute();
      List<Translation> translations = response.getTranslations();
      return translations != null ? translations : ImmutableList.<Translation>of();
    } catch (IOException ex) {
      throw translate(ex);
    }
  }
}

